<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';import SitePublish from './SitePublish.vue';import {getStudio,publishStudio,type StudioPayload} from './content-studio-api';
const payload=ref<StudioPayload|null>(null),query=ref(''),message=ref(''),busy=ref(false);
async function load(){try{payload.value=await getStudio();}catch(e){message.value=(e as Error).message;}}onMounted(load);
const results=computed(()=>{const q=query.value.trim().toLowerCase();if(!q||!payload.value)return [];const p=Object.values(payload.value.document.places).filter(x=>[x.id,x.name.zh,x.name.en,x.region.zh,x.category].some(v=>v?.toLowerCase().includes(q))).slice(0,12);return p;});
async function publish(){if(!payload.value)return;busy.value=true;try{const r=await publishStudio(payload.value,true);message.value=`内容快照 ${r.contentRevision} 已生成。请继续点击下方“更新公开网站”完成构建和上线。`;await load();}catch(e){message.value=(e as Error).message;}finally{busy.value=false;}}
</script>
<template><div v-if="payload" class="workspace-page studio-page"><div class="workspace-title"><div><p class="kicker">Content Studio V6</p><h1>武夷山奶爸维护台</h1><p>直接维护地点、路线、主题、图片与现场记录。先保存草稿，确认预览后再发布。</p></div><span class="revision-chip">草稿 {{payload.draftRevision}}<br><small>{{payload.publishedRevision||'尚未发布'}}</small></span></div><p v-if="message" class="inline-message">{{message}}</p>
<label class="studio-search"><span>搜索地点、路线、主题……</span><input v-model="query" placeholder="野猴谷、WY-0030、桐木、红茶"></label><div v-if="results.length" class="studio-search-results"><RouterLink v-for="place in results" :key="place.id" :to="`/studio/places/${place.id}`"><strong>{{place.name.zh}}</strong><small>{{place.id}} · {{place.region.zh}}</small></RouterLink></div>
<section class="studio-launch-grid"><RouterLink to="/studio/map"><b>🗺</b><strong>地图</strong><span>{{payload.dashboard.stats.places}} 个公开地点</span></RouterLink><RouterLink to="/studio/routes"><b>🛣</b><strong>路线</strong><span>{{payload.dashboard.stats.routes}} 条公开路线</span></RouterLink><RouterLink to="/studio/places"><b>📍</b><strong>地点</strong><span>{{Object.keys(payload.document.places).length}} 个地点</span></RouterLink><RouterLink to="/studio/themes"><b>🧭</b><strong>兴趣主题</strong><span>{{payload.dashboard.stats.themes}} 个公开主题</span></RouterLink><RouterLink to="/studio/media"><b>🖼</b><strong>照片与媒体</strong><span>查看封面与缺图地点</span></RouterLink><RouterLink to="/studio/issues"><b>✓</b><strong>需要处理</strong><span>{{payload.dashboard.issues.length}} 项提醒</span></RouterLink><RouterLink to="/studio/history"><b>🕘</b><strong>修改历史</strong><span>查看差异与恢复</span></RouterLink><RouterLink to="/studio/help"><b>?</b><strong>怎么维护</strong><span>手机现场操作说明</span></RouterLink></section>
<section class="studio-summary"><h2>当前内容</h2><div><span><b>{{payload.dashboard.stats.coreStops}}</b>核心停留点</span><span><b>{{payload.dashboard.stats.routeSegments}}</b>路线段</span><span><b>{{payload.dashboard.stats.routePoints}}</b>路线源点</span></div></section>
<section class="studio-publish-panel"><div><h2>发布修改</h2><p>保存内容版本并生成不可变快照。网站构建失败时，当前公开版本保持不变。</p></div><button class="primary-action" :disabled="busy" @click="publish">{{busy?'正在生成快照…':'生成发布快照'}}</button></section><SitePublish/></div><p v-else class="workspace-page">正在读取维护台…</p></template>
